async (page) => {
  const br = page.context().browser();
  const ctx = await br.newContext({viewport:{width:1920,height:1080},locale:'en-US'});
  const cp = await ctx.newPage();
  await cp.goto('http://10.17.1.66:3001/en/create', {waitUntil:'domcontentloaded'});
  await cp.waitForTimeout(9000);
  const res = {};
  const close = cp.locator('.purchase-gift-modal img[src*="colos_pop_btn_close"]').first();
  res.closeCount = await close.count();
  if (res.closeCount) { await close.click(); await cp.waitForTimeout(1500); }
  res.modalAfter = await cp.locator('.purchase-gift-modal').count();
  res.clickableAfter = await cp.evaluate(() => {
    const el = Array.from(document.querySelectorAll('div.cursor-pointer')).find(d => (d.innerText||'').trim() === 'Start from a Photo');
    if (!el) return 'not-found';
    const r = el.getBoundingClientRect();
    const top = document.elementFromPoint(r.x + r.width/2, r.y + r.height/2);
    return (top === el || el.contains(top)) ? 'clickable' : ('blocked-by ' + (top ? top.tagName : 'null'));
  });
  await cp.screenshot({path:'artifacts/2026-09-14_stable_regression_all_archived/evidence/mcp_drift_20260914/create_after_close2.png'});
  await ctx.close();
  return JSON.stringify(res);
}
